import React, { useState } from "react";
import { useHistory } from "react-router-dom"; // Changé de useNavigate à useHistory
import { AddCar } from "../../services/ApiCar";

export default function CardAddVoiture() {
  const history = useHistory(); // Changé de navigate à history
  const [newCar, setNewCar] = useState({
    matricule: "",
    model: "",
    libelle: "",
    prix: "",
    prix_jour: "",
    couleur: "",
    voiture_image: "",
  });

  const [errors, setErrors] = useState({});

  const handleChange = (e) => {
    const { name, value } = e.target;
    setNewCar({ ...newCar, [name]: value });
    if (errors[name]) {
      setErrors({...errors, [name]: ''});
    }
  };

  const validateForm = () => {
    const newErrors = {};
    let isValid = true;

    if (!newCar.matricule.trim()) {
      newErrors.matricule = 'Matricule est requis';
      isValid = false;
    }
    // ... le reste de la validation reste inchangé
    setErrors(newErrors);
    return isValid;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
  
    if (!validateForm()) {
      return;
    }

    const formData = new FormData();
    for (const key in newCar) {
      formData.append(key, newCar[key]);
    }
  
    try {
      await AddCar(formData);
      alert('Voiture ajoutée avec succès!');
      history.push("/admin/voitures"); // Changé de navigate à history.push
    } catch (error) {
      console.log(error);
      alert('Erreur lors de l\'ajout de la voiture. Veuillez réessayer.');
    }
  };

  return (
    <>
      <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
        <div className="rounded-t bg-white mb-0 px-6 py-6">
          <div className="text-center flex justify-between">
            <h6 className="text-blueGray-700 text-xl font-bold">Ajouter une nouvelle voiture</h6>
            <button
              className="bg-lightBlue-500 text-white active:bg-lightBlue-600 font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md outline-none focus:outline-none mr-1 ease-linear transition-all duration-150"
              type="button"
              onClick={() => history.push("/admin/voitures")} // Changé ici aussi
            >
              Retour
            </button>
          </div>
        </div>

        <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
          <form onSubmit={handleSubmit}>
            {/* ... vos champs de formulaire ... */}

            <div className="text-center mt-6">
              <button
                type="button"
                onClick={() => history.push("/admin/voitures")} // Changé ici
                className="bg-gray-500 text-white active:bg-gray-600 font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md outline-none focus:outline-none mr-4 ease-linear transition-all duration-150"
              >
                Annuler
              </button>
              <button
                type="submit"
                className="bg-lightBlue-500 text-white active:bg-lightBlue-600 font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md outline-none focus:outline-none mr-1 ease-linear transition-all duration-150"
              >
                Ajouter Voiture
              </button>
            </div>
          </form>
        </div>
      </div>
    </>
  );
}
